insert into public.meals(app_id,is_system,name,servings,notes,reference,total_time_minutes,complexity,image,meal_slots,nutrition_notes,unmeasured_ingredients) values ('meal-sticky-teriyaki-chicken',true,'Sticky Teriyaki Chicken',4,'1. Cook rice according to packet instructions.
2. Fry the diced chicken in a pan until golden and cooked through; check the thickest pieces reach 74°C (165°F).
3. Add garlic, soy sauce, honey, and teriyaki sauce.
4. Simmer for 3–4 minutes until sticky.
5. Portion with rice and top with sesame seeds and spring onion.
6. Add an extra sauce pot if desired.','https://www.tiktok.com/@lazymealprep8/photo/7685839537762815254?image_index=5',30,'easy','{"kind":"asset","id":"sticky-teriyaki-chicken"}'::jsonb,array['lunch','dinner'],'Ingredient-calculated estimate for 4 equal servings, using USDA FoodData Central SR Legacy records. Chicken is weighed raw, skinless and boneless; 250 g jasmine rice uses uncooked enriched long-grain white rice as the closest USDA proxy. Generic ready-to-serve teriyaki sauce: 1 tbsp = 18 g; with the confirmed 15 ml tablespoon, 80 ml = 96 g. Soy sauce: 16 g/tbsp; honey: 21 g/tbsp; minced garlic: 2.8 g/tsp. All listed sauce is counted as eaten. Sauce brands and retained sauce vary. Sesame seeds, spring onion, optional extra sauce and unspecified frying oil are excluded from nutrition and generated grocery quantities. Soy sauce and the teriyaki proxy contain soy and wheat; sesame garnish remains relevant to allergy checks. Source-reported macros supplied with the recipe: approximately 520 kcal, 48 g protein, 60 g carbs, 9 g fat per serving; unverified and retained for comparison, not used as the calculated totals. The generated cover is illustrative.','[{"name":"Sesame seeds","measurement":"For garnish; amount not specified"},{"name":"Spring onion","measurement":"For garnish; amount not specified"}]'::jsonb);
