insert into public.meals(app_id,is_system,name,servings,notes,reference,total_time_minutes,complexity,image,meal_slots,nutrition_notes,unmeasured_ingredients) values ('meal-chicken-burrito-protein-boxes',true,'Chicken Burrito Protein Boxes',4,'1. Season chicken with smoked paprika and garlic powder.
